/* Akses user: tombol yang diklik (satu, beberapa, atau semua). Disimpan di sheet sebagai kode: ADMIN | SEMUA | TEKNIK,KI,CAT,CK,PS,CS,LAS,PEM (sebagian atau semua).
   APPROVAL (Group Head / Section Head) berdiri sendiri: hanya melihat + menyetujui; boleh ditambahkan ke kode lain, mis. "CK,APPROVAL". */
var AK_JOBS = [['TEKNIK', 'Teknik'], ['KI', 'Keindahan'], ['CAT', 'Cat'], ['CK', 'CK'], ['PS', 'PS'], ['CS', 'CS'], ['LAS', 'Las'], ['PEM', 'PEM']];
function akParse(s) {
  var o = { admin: false, apv: false, izin: false, rsv: false, ls: false, set: {} };
  String(s == null ? '' : s).toUpperCase().split(/[^A-Z]+/).forEach(function (w) {
    if (!w) return;
    if (w === 'APPROVAL' || w === 'APPROVER') o.apv = true;
    else if (w === 'IZINPKL') o.izin = true;
    else if (w === 'RESERVASI') o.rsv = true;
    else if (w === 'LAPSERVICE' || w === 'LAPORAN' || w === 'LAPSVC') o.ls = true;
    else if (w === 'ADMIN') o.admin = true;
    else if (w === 'SEMUA' || w === 'ALL') AK_JOBS.forEach(function (x) { o.set[x[0]] = 1; });
    else if (w === 'KEINDAHAN') o.set.KI = 1;
    else if (w === 'TB' || w === 'TABRAK') { o.set.CAT = 1; o.set.LAS = 1; o.set.PEM = 1; }      /* kode lama: seluruh Tabrak */
    else if (AK_JOBS.some(function (x) { return x[0] === w; })) o.set[w] = 1;
  });
  return o;
}
function akAll(o) { return AK_JOBS.every(function (x) { return o.set[x[0]]; }); }
function akBase(o) {
  if (o.admin) return 'ADMIN';
  if (akAll(o)) return 'SEMUA';
  return AK_JOBS.filter(function (x) { return o.set[x[0]]; }).map(function (x) { return x[0]; }).join(',');
}
function akVal(o) {
  var b = akBase(o), t = [];
  if (b) t.push(b);
  if (!o.admin && o.rsv) t.push('RESERVASI');          /* Admin sudah termasuk semua menu */
  if (!o.admin && o.ls) t.push('LAPSERVICE');
  if (o.apv) t.push('APPROVAL');
  if (o.izin && !o.apv) t.push('IZINPKL');          /* Approval sudah termasuk meng-ACC izin PKL */
  return t.join(',');
}
function akLb(s) {
  var o = akParse(s), b = akBase(o), t;
  if (o.admin) t = 'Admin (semua pekerjaan + kelola user)';
  else {
    var pt = [];
    if (b === 'SEMUA') pt.push('Semua pekerjaan');
    else if (b) pt.push(AK_JOBS.filter(function (x) { return o.set[x[0]]; }).map(function (x) { return x[1]; }).join(', '));
    if (o.rsv) pt.push('Reservasi');
    if (o.ls) pt.push('Laporan service');
    t = pt.join(', ');
  }
  if (o.apv) return t ? t + ' + Approval' : 'Approval (hanya melihat + menyetujui)';
  if (o.izin) return t ? t + ' + Izin PKL' : 'Izin PKL (hanya meng-ACC mulai kerja PKL)';
  return t || 'Belum ada akses';
}
function akChips(o) {
  var all = !o.admin && akAll(o);
  return AK_JOBS.map(function (x) {
    var on = o.admin || o.set[x[0]];
    return '<button type="button" class="ak-ch' + (on ? ' on' : '') + (o.admin ? ' lk' : '') + '" data-act="usak" data-a="' + x[0] + '" aria-pressed="' + (on ? 'true' : 'false') + '">' + (on ? ic('check', 'sm') : '') + esc(x[1]) + '</button>';
  }).join('') + '<span class="ak-sp"></span>' +
    '<button type="button" class="ak-ch sp' + (all ? ' on' : '') + '" data-act="usak" data-a="SEMUA" aria-pressed="' + (all ? 'true' : 'false') + '">' + (all ? ic('check', 'sm') : '') + 'Semua pekerjaan</button>' +
    '<button type="button" class="ak-ch sp adm' + (o.admin ? ' on' : '') + '" data-act="usak" data-a="ADMIN" aria-pressed="' + (o.admin ? 'true' : 'false') + '">' + (o.admin ? ic('check', 'sm') : ic('shield', 'sm')) + 'Admin</button>' +
    '<button type="button" class="ak-ch sp apv' + (o.apv ? ' on' : '') + '" data-act="usak" data-a="APPROVAL" aria-pressed="' + (o.apv ? 'true' : 'false') + '">' + (o.apv ? ic('check', 'sm') : ic('shield', 'sm')) + 'Approval</button>' +
    '<button type="button" class="ak-ch sp izn' + (o.izin || o.apv ? ' on' : '') + (o.apv ? ' lkv' : '') + '" data-act="usak" data-a="IZINPKL" aria-pressed="' + (o.izin || o.apv ? 'true' : 'false') + '">' + (o.izin || o.apv ? ic('check', 'sm') : ic('shield', 'sm')) + 'Izin PKL</button>' +
    '<span class="ak-sp"></span>' + [['RESERVASI', 'Reservasi', 'rsv'], ['LAPSERVICE', 'Laporan service', 'ls']].map(function (m) {
      var on = o.admin || o.apv || o[m[2]], lk = o.admin ? ' lk' : (o.apv ? ' lkv' : '');          /* Admin dan Approval otomatis punya akses menu ini */
      return '<button type="button" class="ak-ch mn' + (on ? ' on' : '') + lk + '" data-act="usak" data-a="' + m[0] + '" aria-pressed="' + (on ? 'true' : 'false') + '">' + (on ? ic('check', 'sm') : '') + m[1] + '</button>';
    }).join('');
}
function akSum(o) {
  var v = akVal(o), work = !!akBase(o);
  return v ? 'Akses dipilih: <b>' + esc(akLb(v)) + '</b>' + (o.admin ? ' (bisa kelola user)' : '') + (o.apv ? '<br><small>Approval: melihat dan menyetujui pekerjaan yang sudah selesai (Group Head / Section Head), termasuk menu Reservasi dan Laporan service.' + (work ? '' : ' Tidak bisa mengerjakan pekerjaan.') + '</small>' : (!work && !o.admin ? '<br><small>Hanya bisa membuka menu yang dipilih, tidak bisa mengerjakan pekerjaan.</small>' : '')) : 'Belum ada akses dipilih. Klik satu atau lebih tombol di atas.';
}
function usAkUi() {
  var o = S.users.ak, g = $('#us_akg'), h = $('#us_ak'), m = $('#us_aks'), er = $('#us_err');
  if (!o) return;
  if (g) g.innerHTML = akChips(o);
  if (h) h.value = akVal(o);
  if (m) m.innerHTML = akSum(o);
  if (er) er.textContent = '';
}
function usForm(u) {
  var U = S.users, akses = u ? u.akses : (U.setup ? 'ADMIN' : '');
  U.ak = akParse(akses);
  showModal('<div class="sh-head"><b>' + (u ? 'Ubah User' : 'Tambah User') + '</b><button data-act="closemodal" aria-label="Tutup">' + ic('x') + '</button></div>' +
    (U.setup && !u ? '<div class="us-note" style="margin-bottom:4px">User pertama harus berakses <b>Admin</b>.</div>' : '') +
    '<label for="us_nama">Nama</label><input id="us_nama" maxlength="60" autocomplete="off" placeholder="Nama lengkap" value="' + esc(u ? u.nama : '') + '">' +
    '<label for="us_nip">NIP <em>dipakai untuk login</em></label><input id="us_nip" maxlength="20" autocomplete="off" autocapitalize="characters" placeholder="contoh: 12345" value="' + esc(u ? u.nip : '') + '">' +
    '<label>Akses <em>klik satu atau lebih</em></label><input type="hidden" id="us_ak" value="' + esc(akVal(U.ak)) + '"><div class="ak-g" id="us_akg">' + akChips(U.ak) + '</div><div class="ak-sum" id="us_aks">' + akSum(U.ak) + '</div>' +
    '<div class="us-two"><div><label for="us_bg">Bagian <em>opsional</em></label><input id="us_bg" maxlength="40" autocomplete="off" placeholder="Teknik" value="' + esc(u ? u.bagian : '') + '"></div>' +
    '<div><label for="us_jb">Jabatan <em>opsional</em></label><input id="us_jb" maxlength="30" autocomplete="off" placeholder="M1" value="' + esc(u ? u.jabatan : '') + '"></div></div>' +
    (u ? '<label class="us-chk"><input type="checkbox" id="us_on"' + (u.aktif ? ' checked' : '') + '> Aktif (bisa masuk &amp; mengerjakan)</label>' : '') +
    '<div class="us-err" id="us_err"></div>' +
    '<button class="btn full" id="us_save" data-act="ussave" style="margin-top:12px">' + ic('check') + ' Simpan</button>' +
    (u ? '<button class="btn ghost full us-del" id="us_del" data-act="usdel" data-a="' + esc(u.nip) + '">Hapus User</button>' : ''));
  setTimeout(function () { var f = $(u ? '#us_nama' : '#us_nama'); if (f && !u) f.focus(); }, 60);
}

