function pkSyncUi() { var el = $('#pksync'); if (el && S.pk.job && S.view === 'jobpk') el.innerHTML = pkSyncHtml(S.pk.job); }
function pkSync() {
  if (S.pk.busy) return;
  var list = (S.pk.job ? [S.pk.job] : []).concat(S.pk.q), x = null, kind = '', i;
  for (i = 0; i < list.length; i++) { if (pkCPending(list[i])) { x = list[i]; kind = 'c'; break; } }
  if (!x) for (i = 0; i < list.length; i++) { if (pkPending(list[i])) { x = list[i]; kind = 'j'; break; } }
  if (!x) for (i = 0; i < list.length; i++) { if (pkFPending(list[i])) { x = list[i]; kind = 'f'; break; } }
  if (!x) for (i = 0; i < list.length; i++) { if (pkPPending(list[i])) { x = list[i]; kind = 'p'; break; } }
  if (!x) return;
  S.pk.busy = true;
  function fin() {
    S.pk.busy = false; S.pk.q = S.pk.q.filter(pkAnyPending); pkJobSave();
    if (x.cf && S.pk.job === x && S.view === 'jobpk') pkShow(); else { pkSyncUi(); pkPhUi(); }
  }
  function tolak() { toast('Pekerjaan ini sudah dipegang pengguna lain. Pengerjaan Anda tidak dicatat.', true); }
  if (kind === 'c') {
    var cs = pkCSig(x), cc = x.ck, kd = kdOf(x);
    var pay = { k: cc.k, d: cc.d, id: x.id, n: x.n, n0: cc.n0, tg: cc.jm, kl: cc.kl, s: x.s, e: x.e || 0, t: x.t || '', u: x.u || '', td: x.td ? 1 : 0, tc: x.tc || '', lf: x.lf || '' };
    if (kd === 'tb') { pay.rg = cc.rg || ''; pay.fo = cc.fo || []; pay.fs = cc.fs || []; pay.pem = x.e && !x.td && x.pem ? 1 : 0; }
    else if (kd === 'pem' || kd === 'las') { pay.rg = cc.rg || ''; pay.fo = cc.fo || []; pay.cs = cc.cs || []; }
    else { pay.nip = cc.nip; pay.nm = cc.nm; }
    gs(KDC[kd].sv, [pay]).then(function (r) {
      if (x.rv) { x.cerr = ''; }          // dipindah ke Las saat simpanan ini berjalan: hasilnya diabaikan
      else if (r && r.ok === false && r.conflict) { x.cf = r.conflict; x.cerr = ''; phPurge(x); ckFetch(kd, cc.d, true); tolak(); }
      else if (r && r.locked && r.ap) { apApply(x, r.ap, true); x.cy = pkCSig(x); x.cerr = ''; ckAfterSync(x); }
      else { x.cy = cs; x.cerr = ''; ckAfterSync(x); }
      fin(); pkSync();
    }, function (er) { x.cerr = msg(er); S.pk.busy = false; pkJobSave(); pkSyncUi(); });
  } else if (kind === 'j') {
    var sg = pkSig(x), pay = { id: x.id, n: x.n, j: x.j, s: x.s, e: x.e || 0, u: x.u || '', lf: x.lf || '' };
    if (x.sv) pay.sv = x.sv;
    if (x.e) { pay.t = x.j === 'cs' ? csTxt(x) : (x.t || ''); if (x.td) { pay.td = 1; pay.tc = x.tc || ''; } }
    if (x.rv) pay.bt = 1;          // Cat salah klik dipindah ke Las: waktunya dibatalkan di Laporan Jam Mekanik
    gs('jamKerja', [pay]).then(function (r) {
      if (r && r.ok === false && r.conflict) { x.cf = r.conflict; x.err = ''; phPurge(x); tolak(); }
      else if (r && r.locked && r.ap) { apApply(x, r.ap, true); x.ok = 1; x.sg = pkSig(x); x.err = ''; }
      else { x.ok = 1; x.sg = sg; x.err = ''; }
      fin(); pkSync();
    }, function (er) { x.err = msg(er); S.pk.busy = false; pkJobSave(); pkSyncUi(); });
  } else if (kind === 'p') {
    var pk = phNext(x), po = x.ph[pk], pst = po.p, pd = phGet(x, pk);
    if (!pd) { po.p = 0; po.lost = 1; fin(); pkSync(); return; }            // data foto hilang (penyimpanan HP penuh / dibersihkan): minta ambil ulang
    gs('fotoSimpan', [{ id: x.id, n: x.n, j: x.j, s: x.s, u: x.u || '', k: pk, d: pd, lk: x.ck ? x.ck.k : '' }]).then(function () {
      var cur = x.ph[pk];
      if (cur && cur.p === pst) { cur.p = 0; cur.y = pst; cur.n = 0; cur.er = ''; phDrop(x, pk, true); }
      x.perr = ''; fin(); pkSync();
    }, function (er) {
      var cur = x.ph[pk]; if (cur) { cur.n = (cur.n || 0) + 1; cur.er = msg(er); }
      x.perr = msg(er); S.pk.busy = false; pkJobSave(); pkSyncUi(); pkPhUi();
    });
  } else {
    var fs = x.fs;
    gs('fokusSimpan', [{ id: x.id, n: x.n, j: x.j, s: x.s, u: x.u || '', h: x.fh || {}, v: x.fv || {}, ox: x.fo || [], pl: x.fby || '' }]).then(function () { x.fy = fs; x.ferr = ''; fin(); pkSync(); },
      function (er) { x.ferr = msg(er); S.pk.busy = false; pkJobSave(); pkSyncUi(); });
  }
}
