/* ---------- Job Mekanik > Corrective Kendaraan (CK) dan Tabrak (TB): laporan dari sheet lain, dikerjakan satu per satu ---------- */
var KDC = {
  ck: { t: 'Corrective Kendaraan', fn: 'getCK', sv: 'ckSimpan', sheet: 'CK Pengerjaan', lap: 'Laporan CK', nama: 'laporan keluhan', judul: 'Laporan Keluhan Kendaraan', info: 'Dari pengemudi. Tekan Kerjakan untuk mulai.', cari: 'Cari No Mobil, nama, atau keluhan...', tulis: 'Ditulis pengemudi', isi: 'Keluhan' },
  tb: { t: 'Tabrak', fn: 'getTB', sv: 'tbSimpan', sheet: 'TB Pengerjaan', lap: 'Laporan TB', nama: 'laporan tabrak', judul: 'Laporan Kerusakan Tabrak', info: 'Dari form klaim. Tekan Kerjakan untuk mulai.', cari: 'Cari No Registrasi, No Mobil, atau detail...', tulis: 'Ditulis di form', isi: 'Detail kerusakan' },
  pem: { t: 'Tabrak PEM', fn: 'getPEM', sv: 'pemSimpan', sheet: 'PEM Pengerjaan', lap: 'Laporan PEM', nama: 'armada PEM', judul: 'Armada yang Membutuhkan PEM', info: 'Dari pekerjaan Cat. Tekan Kerjakan untuk mulai.', cari: 'Cari No Registrasi, No Mobil, atau detail...', tulis: 'Ditulis di form', isi: 'Detail kerusakan' },
  las: { t: 'Tabrak Las', fn: 'getLAS', sv: 'lasSimpan', sheet: 'Las Pengerjaan', lap: 'Laporan Las', nama: 'armada Las / Ketok', judul: 'Armada Las / Ketok', info: 'Dikirim dari Cat. Tekan Kerjakan untuk mulai.', cari: 'Cari No Registrasi, No Mobil, atau detail...', tulis: 'Ditulis di form', isi: 'Detail kerusakan' }
};
function kdOf(j) { return j && j.j === 'tb' ? 'tb' : (j && j.j === 'pem' ? 'pem' : (j && j.j === 'las' ? 'las' : 'ck')); }          /* jenis pengerjaan -> 'ck' | 'tb' | 'pem' | 'las' */
function kdArg(b) { return b === 'tb' || b === 'pem' || b === 'las' ? b : 'ck'; }
function kdTb(kd) { return kd === 'tb' || kd === 'pem' || kd === 'las'; }
function kdLbl(kd) { return kd === 'pem' ? 'PEM' : (kd === 'las' ? 'Las' : (kd === 'tb' ? 'Tabrak' : 'Keluhan')); }          /* tampilan laporan tabrak (foto kerusakan, No Registrasi) dipakai Cat dan PEM */
