function ckOn(kd) { return S.view === kd; }
/* daftar hari ini disimpan di HP: membuka halaman CK/Tabrak langsung menampilkan data terakhir, lalu diperbarui di latar belakang */
var CKC = 'bka_ckc';
function ckPersist(kd, d) {
  if (d !== todayIso()) return;
  try { var o = JSON.parse(localStorage.getItem(CKC) || 'null'); if (!o || o.d !== d) o = { d: d }; o[kd] = S[kd].rows[d]; localStorage.setItem(CKC, JSON.stringify(o)); } catch (e) {}
}
(function () {
  try {
    var o = JSON.parse(localStorage.getItem(CKC) || 'null');
    if (o && o.d === todayIso()) ['ck', 'tb', 'pem', 'las'].forEach(function (kd) { if (o[kd] && o[kd].rows && o[kd].d === o.d) S[kd].rows[o.d] = o[kd]; });
  } catch (e) {}
})();
function ckIsBusy(C, d) { var t = C.busy[d]; return !!t && Date.now() - t < 60000; }
function ckAnyBusy() { var d, kd, k = ['ck', 'tb', 'pem', 'las']; for (var i = 0; i < k.length; i++) { kd = k[i]; for (d in S[kd].busy) if (ckIsBusy(S[kd], d)) return true; } return false; }
