function fkSave() {
  var j = S.pk.job; if (!j || j.ap) return;
  j.f = j.f || {};
  var all = fkSet(fkJn(j)).all;
  var miss = all.filter(function (fd) { var r = fkRes(fd, j.f[fd.k]); return r === 'empty' || r === 'inv'; });
  if (miss.length) {
    miss.forEach(function (fd) { var el = $('#fk_' + fd.k); if (el) el.classList.add('bad'); });
    var first = $('#fk_' + miss[0].k);
    toast('Lengkapi ' + miss.length + ' isian yang masih kosong atau salah. Semua isian wajib diisi.', true);
    if (first) { try { first.scrollIntoView({ block: 'center', behavior: 'smooth' }); } catch (e) {} if (first.focus && first.tagName === 'INPUT') first.focus({ preventScroll: true }); }
    return;
  }
  var v = {}; all.forEach(function (fd) { v[fd.k] = String(j.f[fd.k]).replace(/\s+/g, ' ').trim(); });
  var h = fkHeadData(j);
  if (j.fbv && JSON.stringify(v) !== j.fbv) j.fby = '';          /* direvisi mekanik yang meneruskan: Pelaksana jadi nama yang menyimpan */
  j.fcl = '';
  j.fv = v; j.fh = { sv: h.sv === '-' ? '' : h.sv, od: h.od === '-' ? '' : h.od }; j.fo = fkCount(j).out; j.fs = Date.now(); j.fd = 0; j.ferr = '';
  pkJobSave(); pkSync(); toast('Form Fokus tersimpan'); go('jobpk');
}

